import { BookmarkPlus, CornerDownRight, FileSearch, Search, X } from 'lucide-react'
import type { KeyboardEvent } from 'react'
import { useEffect, useRef, useState } from 'react'

import { Button } from '@/components/ui/button'
import type { SearchResult } from '@/vault/types'
import { containDialogTabKey } from '@/workbench/dialog-focus'

interface SearchPaneProps {
  open: boolean
  initialQuery?: string
  initialQueryRequest?: number
  onOpenChange: (open: boolean) => void
  onSelectResult: (result: SearchResult) => Promise<boolean>
  onBookmarkQuery?: (query: string) => void | Promise<void>
}

export function SearchPane({
  open,
  initialQuery = '',
  initialQueryRequest = 0,
  onOpenChange,
  onSelectResult,
  onBookmarkQuery
}: SearchPaneProps): React.JSX.Element | null {
  const [query, setQuery] = useState('')
  const [results, setResults] = useState<SearchResult[]>([])
  const [isSearching, setIsSearching] = useState(false)
  const [isOpening, setIsOpening] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const inputRef = useRef<HTMLInputElement | null>(null)

  useEffect(() => {
    if (!open) {
      return
    }

    setQuery(initialQuery)
    window.setTimeout(() => inputRef.current?.focus(), 0)
  }, [initialQuery, initialQueryRequest, open])

  useEffect(() => {
    if (!open) {
      return
    }

    const trimmedQuery = query.trim()

    if (!trimmedQuery) {
      return
    }

    let cancelled = false
    const timer = window.setTimeout(() => {
      setIsSearching(true)
      setError(null)

      void window.indexApi
        .search(trimmedQuery, 50)
        .then((nextResults) => {
          if (!cancelled) {
            setResults(nextResults)
          }
        })
        .catch((searchError: unknown) => {
          if (!cancelled) {
            setResults([])
            setError(formatError(searchError))
          }
        })
        .finally(() => {
          if (!cancelled) {
            setIsSearching(false)
          }
        })
    }, 180)

    return () => {
      cancelled = true
      window.clearTimeout(timer)
    }
  }, [open, query])

  if (!open) {
    return null
  }

  const selectResult = async (result: SearchResult): Promise<void> => {
    if (isOpening) {
      return
    }

    setIsOpening(true)
    setError(null)
    try {
      if (await onSelectResult(result)) {
        onOpenChange(false)
      } else {
        setError(`Could not open “${result.note.relativePath}”. Your current item is still active.`)
      }
    } catch (openError) {
      setError(formatError(openError))
    } finally {
      setIsOpening(false)
    }
  }

  const handleKeyDown = (event: KeyboardEvent<HTMLElement>): void => {
    if (event.key === 'Escape') {
      event.preventDefault()
      event.stopPropagation()
      onOpenChange(false)
      return
    }

    if (event.target === inputRef.current && event.key === 'Enter' && results[0]) {
      event.preventDefault()
      void selectResult(results[0])
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-start justify-center overscroll-contain bg-background/75 px-4 pt-[12vh]"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) {
          onOpenChange(false)
        }
      }}
    >
      <div
        role="dialog"
        aria-modal="true"
        aria-label="Search notes"
        tabIndex={-1}
        className="flex max-h-[76vh] w-full max-w-2xl flex-col overflow-hidden border-2 border-foreground bg-card shadow-[4px_4px_0_0_var(--foreground)]"
        onKeyDown={(event) => {
          handleKeyDown(event)
          containDialogTabKey(event, event.currentTarget)
        }}
      >
        <div className="flex h-12 shrink-0 items-center gap-2 border-b-2 border-foreground px-3 focus-within:ring-[3px] focus-within:ring-inset focus-within:ring-ring/50">
          <Search className="size-4 text-muted-foreground" aria-hidden="true" />
          <input
            ref={inputRef}
            name="search-query"
            autoComplete="off"
            spellCheck={false}
            value={query}
            className="h-full min-w-0 flex-1 bg-transparent font-mono text-sm outline-none placeholder:text-muted-foreground"
            placeholder="Search notes, tag:idea, path:notes, file:daily, /regex/…"
            aria-label="Search notes"
            onChange={(event) => setQuery(event.target.value)}
          />
          <Button
            type="button"
            size="icon-xs"
            variant="ghost"
            title="Bookmark this search"
            aria-label="Bookmark this search"
            disabled={!query.trim()}
            onClick={() => void onBookmarkQuery?.(query.trim())}
          >
            <BookmarkPlus className="size-3.5" aria-hidden="true" />
          </Button>
          <Button
            type="button"
            size="icon-xs"
            variant="ghost"
            title="Close"
            aria-label="Close search"
            onClick={() => onOpenChange(false)}
          >
            <X className="size-3.5" aria-hidden="true" />
          </Button>
        </div>

        <div className="min-h-0 flex-1 overflow-auto p-2">
          {!query.trim() ? (
            <EmptySearchState label="Use text, tag:, path:, file:, or /regex/." />
          ) : error ? (
            <div
              role="alert"
              className="border-2 border-destructive bg-destructive/10 p-3 font-mono text-[12px] uppercase tracking-wider text-destructive"
            >
              {error}
            </div>
          ) : isSearching ? (
            <EmptySearchState label="Searching…" />
          ) : results.length === 0 ? (
            <EmptySearchState label="No matches." />
          ) : (
            <div className="space-y-1">
              {results.map((result) => (
                <button
                  key={`${result.note.relativePath}-${result.heading?.id ?? 'note'}-${result.snippet}`}
                  type="button"
                  data-page-preview-path={result.note.relativePath}
                  className="w-full px-3 py-2.5 text-left transition-colors hover:bg-foreground hover:text-background focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-none motion-reduce:transition-none"
                  title={result.note.relativePath}
                  disabled={isOpening}
                  onClick={() => void selectResult(result)}
                >
                  <div className="truncate text-sm font-medium">{result.note.title}</div>
                  <div className="mt-0.5 truncate text-xs text-muted-foreground">
                    {result.note.relativePath}
                  </div>
                  {result.heading ? (
                    <div className="mt-1 flex min-w-0 items-center gap-1.5 font-mono text-[10px] font-bold uppercase tracking-wider text-instrument-blue">
                      <CornerDownRight className="size-3 shrink-0" aria-hidden="true" />
                      <span className="shrink-0">H{result.heading.depth}</span>
                      <span className="truncate">{result.heading.text}</span>
                    </div>
                  ) : null}
                  {result.matches.length > 0 ? (
                    <div className="mt-1 flex flex-wrap gap-1">
                      {result.matches.map((match) => (
                        <span
                          key={match}
                          className="border border-current px-1 py-0.5 font-mono text-[10px] uppercase tracking-wider opacity-75"
                        >
                          {match}
                        </span>
                      ))}
                    </div>
                  ) : null}
                  <div className="mt-1 line-clamp-2 text-sm text-muted-foreground">
                    {result.snippet || result.note.title}
                  </div>
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

function EmptySearchState({ label }: { label: string }): React.JSX.Element {
  return (
    <div className="flex h-40 flex-col items-center justify-center gap-2 font-mono text-[11px] uppercase tracking-wider text-muted-foreground">
      <FileSearch className="size-5" aria-hidden="true" />
      <div>{label}</div>
    </div>
  )
}

function formatError(error: unknown): string {
  if (error instanceof Error) {
    return error.message
  }

  return String(error)
}
